syntax = "proto3";
package user.v1;

message GetUserRequest {
  int64 id = 1;                 // 1-15 号 key 只占 1 字节，留给高频字段
  reserved 2, 3;                // 历史删除字段的 tag 必须 reserved
  reserved "deprecated_name";
}

message User {
  int64 id = 1;
  string name = 2;
  repeated string roles = 3;    // repeated 默认 packed，多个值压在一个 length-delimited 块里
  google.protobuf.Int32Value age = 4; // wrap 类型用来区分"未设置"和"显式 0"
}

service UserService {
  rpc GetUser(GetUserRequest) returns (User);                 // Unary
  rpc WatchUsers(GetUserRequest) returns (stream User);       // Server streaming
  rpc ImportUsers(stream User) returns (GetUserRequest);      // Client streaming
  rpc Chat(stream User) returns (stream User);                // Bidirectional
}
